"""Tokenizer and recursive-descent SQL parser, implemented for this project."""
import re
from common import Token, Expr, SQLError, Column, RESERVED, INTEGER_MIN, INTEGER_MAX


def tokenize(sql):
    out = []
    i, n = 0, len(sql)
    variable = 0
    while i < n:
        c = sql[i]
        if c.isspace(): i += 1; continue
        if sql.startswith('--',i):
            j = sql.find('\n',i); i = n if j<0 else j+1; continue
        if sql.startswith('/*',i):
            j = sql.find('*/',i+2); i = n if j<0 else j+2; continue
        start = i
        if c in "xX" and i+1<n and sql[i+1] == "'":
            j = sql.find("'",i+2)
            if j < 0: raise SQLError('unrecognized token: "'+sql[i:]+'"',i)
            raw = sql[i:j+1]
            try: val = bytes.fromhex(sql[i+2:j])
            except ValueError: raise SQLError('unrecognized token: "'+raw+'"', i)
            out.append(Token(raw,val,'blob',i,j+1)); i=j+1; continue
        if c in "'\"`[":
            q = ']' if c=='[' else c
            i+=1; val=''; closed=False
            while i<n:
                if sql[i]==q:
                    if q != ']' and i+1<n and sql[i+1]==q:
                        val+=q; i+=2; continue
                    i+=1; closed=True; break
                val+=sql[i]; i+=1
            if not closed: raise SQLError('unrecognized token: "'+sql[start:]+'"', start)
            out.append(Token(sql[start:i],val,'string' if c=="'" else 'quoted',start,i)); continue
        if c.isdigit() or (c=='.' and i+1<n and sql[i+1].isdigit()):
            m = re.match(r'0[xX][0-9a-fA-F_]+|(?:(?:[0-9][0-9_]*(?:\.[0-9_]*)?)|(?:\.[0-9][0-9_]*))(?:[eE][+-]?[0-9][0-9_]*)?',sql[i:])
            raw=m.group(0); i+=len(raw); clean=raw.replace('_','')
            try:
                if clean.lower().startswith('0x'):
                    val=int(clean[2:],16)
                    if val>2**64-1: raise SQLError('hex literal too big: '+raw,start)
                    if val>INTEGER_MAX: val-=2**64
                elif '.' in clean or 'e' in clean.lower(): val=float(clean)
                else:
                    val=int(clean)
                    if val>INTEGER_MAX: val=float(val)
            except ValueError: raise SQLError('unrecognized token: "'+raw+'"',start)
            out.append(Token(raw,val,'number',start,i)); continue
        if c in ':@$?':
            if c=='?':
                i+=1
                while i<n and sql[i].isdigit(): i+=1
                if i>start+1: variable=int(sql[start+1:i])
                else: variable+=1
                val='?'+str(variable)
            else:
                i+=1
                while i<n and (sql[i].isalnum() or sql[i] in '_$:' or ord(sql[i])>127): i+=1
                if c=='$' and i<n and sql[i]=='(':
                    j=sql.find(')',i); i=n if j<0 else j+1
                val=sql[start:i]
            out.append(Token(sql[start:i],val,'param',start,i)); continue
        if c.isalpha() or c=='_' or ord(c)>127:
            i+=1
            while i<n and (sql[i].isalnum() or sql[i] in '_$' or ord(sql[i])>127): i+=1
            out.append(Token(sql[start:i],sql[start:i],'word',start,i)); continue
        op = next((o for o in ('->>','||','<<','>>','<=','>=','==','!=','<>','->') if sql.startswith(o,i)),None)
        if op:
            i+=len(op); out.append(Token(op,op,'op',start,i)); continue
        if c in '(),;.+-*/%~&|=<>':
            out.append(Token(c,c,'op',i,i+1)); i+=1; continue
        raise SQLError('unrecognized token: "'+c+'"',i)
    out.append(Token('',None,'eof',n,n))
    return out

class Parser:
    def __init__(self, sql, tokens=None):
        self.sql=sql
        self.tokens=tokens if tokens is not None else tokenize(sql)
        self.i=0
    @property
    def t(self): return self.tokens[min(self.i,len(self.tokens)-1)]
    def peek(self, off=0): return self.tokens[min(self.i+off,len(self.tokens)-1)]
    def at(self,*words): return self.t.up in words
    def pop(self):
        t=self.t; self.i+=1; return t
    def take(self,word):
        if self.at(word): return self.pop()
        return None
    def expect(self,word):
        if not self.at(word): self.error()
        return self.pop()
    def error(self,t=None,msg=None):
        t=t or self.t
        if msg is None:
            msg='incomplete input' if t.kind=='eof' else 'near "'+t.raw+'": syntax error'
        raise SQLError(msg,None if t.kind=='eof' else t.pos)
    def ident(self):
        t=self.t
        if t.kind not in ('word','quoted','string'): self.error()
        self.pop(); return str(t.value)
    def fullname(self):
        a=self.ident()
        if self.take('.'):
            b=self.ident(); return [a,b]
        return [a]
    def finish_expr(self,e,start):
        e.pos = start
        e.end = self.tokens[max(0,self.i-1)].end
        e.text = self.sql[start:e.end]
        return e
    def expr(self,minbp=0):
        t=self.pop(); start=t.pos
        if t.kind in ('string','number','blob'):
            left=Expr('literal',value=t.value)
        elif t.kind=='param': left=Expr('param',value=t.value)
        elif t.up in ('NULL','TRUE','FALSE'):
            left=Expr('literal',value={'NULL':None,'TRUE':1,'FALSE':0}[t.up],extra=t.up)
        elif t.up in ('CURRENT_DATE','CURRENT_TIME','CURRENT_TIMESTAMP'):
            left=Expr('function',value=t.up.lower())
        elif t.up in ('+','-','~','NOT'):
            left=Expr('unary',[self.expr(25 if t.up=='NOT' else 85)],t.up)
        elif t.up=='(':
            if self.at('SELECT','WITH','VALUES'):
                q=self.query(); self.expect(')'); left=Expr('subquery',value=q)
            else:
                left=self.expr()
                if self.take(','):
                    vals=[left,self.expr()]
                    while self.take(','): vals.append(self.expr())
                    left=Expr('row',vals)
                self.expect(')')
        elif t.up=='CASE':
            base=None
            if not self.at('WHEN'): base=self.expr()
            pairs=[]
            while self.take('WHEN'):
                c=self.expr(); self.expect('THEN'); v=self.expr(); pairs.append((c,v))
            other=None
            if self.take('ELSE'): other=self.expr()
            self.expect('END')
            left=Expr('case', value=(base,pairs,other))
        elif t.up=='CAST':
            self.expect('('); e=self.expr(); self.expect('AS'); ty=[]
            while not self.at(')') and self.t.kind!='eof': ty.append(self.pop().raw)
            self.expect(')'); left=Expr('cast',[e],value=' '.join(ty))
        elif t.up=='EXISTS':
            self.expect('('); q=self.query(); self.expect(')'); left=Expr('exists',value=q)
        elif t.up=='*': left=Expr('star')
        elif t.kind in ('word','quoted'):
            parts=[str(t.value)]
            if self.take('('):
                args=[]; distinct=bool(self.take('DISTINCT'))
                if not self.at(')'):
                    args.append(self.expr())
                    while self.take(','): args.append(self.expr())
                order=[]
                if self.take('ORDER'):
                    self.expect('BY'); order=self.order_terms()
                self.expect(')')
                filt=None; win=None
                if self.take('FILTER'):
                    self.expect('('); self.expect('WHERE'); filt=self.expr(); self.expect(')')
                if self.take('OVER'):
                    if self.take('('): win=self.window_spec(); self.expect(')')
                    else: win={'name':self.ident()}
                left=Expr('function',args,str(t.value).lower(),extra={'distinct':distinct,'filter':filt,'order':order,'window':win})
            else:
                while self.take('.'):
                    if self.take('*'):
                        parts.append('*'); break
                    parts.append(self.ident())
                if parts[-1]=='*': left=Expr('star',value=parts[:-1])
                else: left=Expr('column',value=parts,extra=t.raw.startswith('"'))
        else: self.error(t)
        self.finish_expr(left,start)
        while True:
            t=self.t; op=t.up; neg=False
            if op=='COLLATE':
                if 90<minbp: break
                self.pop(); name=self.ident()
                left=self.finish_expr(Expr('collate',[left],name),start); continue
            if op in ('ISNULL','NOTNULL'):
                if 30<minbp: break
                self.pop(); left=self.finish_expr(Expr('isnull',[left],op=='NOTNULL'),start); continue
            if op=='NOT' and self.peek(1).up=='NULL':
                if 30<minbp: break
                self.pop(); self.pop(); left=self.finish_expr(Expr('isnull',[left],True),start); continue
            if op=='NOT' and self.peek(1).up in ('IN','LIKE','GLOB','REGEXP','MATCH','BETWEEN'):
                neg=True; op=self.peek(1).up
            bp={'OR':10,'AND':20,'=':30,'==':30,'!=':30,'<>':30,'IS':30,'IN':30,'LIKE':30,'GLOB':30,'REGEXP':30,'MATCH':30,'BETWEEN':30,'<':40,'<=':40,'>':40,'>=':40,'&':50,'|':50,'<<':50,'>>':50,'+':60,'-':60,'*':70,'/':70,'%':70,'||':80,'->':80,'->>':80}.get(op,-1)
            if bp<minbp: break
            self.pop()
            if neg: self.pop()
            if op=='IS':
                isnot=bool(self.take('NOT'))
                if self.take('DISTINCT'):
                    self.expect('FROM'); isnot=not isnot
                right=self.expr(bp+1)
                left=self.finish_expr(Expr('binary',[left,right],value='IS NOT' if isnot else 'IS'),start)
            elif op=='BETWEEN':
                low=self.expr(bp+1); self.expect('AND'); high=self.expr(bp+1)
                left=self.finish_expr(Expr('between',[left,low,high],neg),start)
            elif op=='IN':
                args=[]; q=None
                if self.take('('):
                    if self.at('SELECT','WITH','VALUES'): q=self.query()
                    elif not self.at(')'):
                        args.append(self.expr())
                        while self.take(','): args.append(self.expr())
                    self.expect(')')
                else:
                    name=self.fullname(); q={'kind':'select','items':[(Expr('star'),None)],'from':[({'name':name},'FIRST',None,[]) ]}
                left=self.finish_expr(Expr('in',[left]+args,value=q,extra=neg),start)
            elif op in ('LIKE','GLOB','REGEXP','MATCH'):
                right=self.expr(bp+1); esc=None
                if self.take('ESCAPE'): esc=self.expr(bp+1)
                left=self.finish_expr(Expr('pattern',[left,right]+([esc] if esc else []),op,extra=neg),start)
            else:
                right=self.expr(bp+1)
                left=self.finish_expr(Expr('binary',[left,right],op),start)
        return left

    def exprlist(self):
        a=[self.expr()]
        while self.take(','): a.append(self.expr())
        return a
    def order_terms(self):
        terms=[]
        while True:
            e=self.expr(); direction='ASC'; nulls=None
            if self.at('ASC','DESC'): direction=self.pop().up
            if self.take('NULLS'):
                if not self.at('FIRST','LAST'): self.error()
                nulls=self.pop().up
            terms.append((e,direction,nulls))
            if not self.take(','): break
        return terms
    def window_spec(self):
        spec={}
        if self.t.kind in ('word','quoted') and not self.at('PARTITION','ORDER','ROWS','RANGE','GROUPS',')'):
            spec['name']=self.ident()
        if self.take('PARTITION'):
            self.expect('BY'); spec['partition']=self.exprlist()
        if self.take('ORDER'):
            self.expect('BY'); spec['order']=self.order_terms()
        if self.at('ROWS','RANGE','GROUPS'):
            spec['frame_type']=self.pop().up
            def bound():
                if self.take('UNBOUNDED'):
                    t=self.pop()
                    if t.up not in ('PRECEDING','FOLLOWING'): self.error(t)
                    return (None,t.up)
                if self.take('CURRENT'):
                    self.expect('ROW'); return (0,'CURRENT')
                e=self.expr(31); t=self.pop()
                if t.up not in ('PRECEDING','FOLLOWING'): self.error(t)
                return (e,t.up)
            if self.take('BETWEEN'):
                spec['start']=bound(); self.expect('AND'); spec['end']=bound()
            else:
                spec['start']=bound(); spec['end']=(0,'CURRENT')
            if self.take('EXCLUDE'):
                s=self.pop().up
                if s=='CURRENT': self.expect('ROW')
                if s=='NO': self.expect('OTHERS')
                spec['exclude']=s
        return spec
    def select_items(self):
        items=[]
        while True:
            e=self.expr(); alias=None
            if self.take('AS'): alias=self.ident()
            elif self.t.kind in ('word','quoted','string') and self.t.up not in RESERVED | {'STRICT'}:
                alias=self.ident()
            items.append((e,alias))
            if not self.take(','): break
        return items
    def source(self):
        if self.take('('):
            if self.at('SELECT','WITH','VALUES'):
                s={'query':self.query()}
            else:
                s={'joined':self.from_clause()}
            self.expect(')')
        else:
            s={'name':self.fullname()}
            if self.take('('):
                s['args']=[] if self.at(')') else self.exprlist()
                self.expect(')')
        if self.take('AS'): s['alias']=self.ident()
        elif self.t.kind in ('word','quoted','string') and self.t.up not in RESERVED | {'STRICT'}:
            s['alias']=self.ident()
        if self.take('INDEXED'):
            self.expect('BY'); s['index']=self.ident()
        elif self.take('NOT'):
            self.expect('INDEXED'); s['index']=False
        return s
    def from_clause(self):
        sources=[(self.source(),'FIRST',None,[])]
        while True:
            jt=[]
            if self.take(','): jt=['CROSS']
            elif self.at('JOIN','LEFT','RIGHT','FULL','INNER','CROSS','NATURAL','OUTER'):
                while not self.at('JOIN') and self.t.kind!='eof': jt.append(self.pop().up)
                self.expect('JOIN')
                if not jt: jt=['INNER']
            else: break
            s=self.source(); on=None; using=[]
            if self.take('ON'): on=self.expr()
            elif self.take('USING'):
                self.expect('('); using=[self.ident()]
                while self.take(','): using.append(self.ident())
                self.expect(')')
            sources.append((s,' '.join(jt),on,using))
        return sources
    def with_clause(self):
        self.expect('WITH'); recursive=bool(self.take('RECURSIVE')); ctes=[]
        while True:
            name=self.ident(); cols=[]
            if self.take('('):
                cols=[self.ident()]
                while self.take(','): cols.append(self.ident())
                self.expect(')')
            self.expect('AS')
            self.take('NOT'); self.take('MATERIALIZED')
            self.expect('('); q=self.query(); self.expect(')')
            ctes.append((name,cols,q))
            if not self.take(','): break
        return ctes,recursive
    def query(self):
        ctes=[]; recursive=False
        if self.at('WITH'): ctes,recursive=self.with_clause()
        q=self.query_core(); comps=[]
        while self.at('UNION','INTERSECT','EXCEPT'):
            op=self.pop().up
            if op=='UNION' and self.take('ALL'): op='UNION ALL'
            comps.append((op,self.query_core()))
        q['compounds']=comps
        if self.take('ORDER'):
            self.expect('BY'); q['order']=self.order_terms()
        if self.take('LIMIT'):
            a=self.expr(); b=None
            if self.take('OFFSET'): b=self.expr()
            elif self.take(','): b=a; a=self.expr()
            q['limit']=(a,b)
        if ctes: q['with']=ctes; q['recursive']=recursive
        return q
    def query_core(self):
        if self.take('VALUES'):
            rows=[]
            while True:
                self.expect('('); rows.append(self.exprlist()); self.expect(')')
                if not self.take(','): break
            return {'kind':'values','rows':rows}
        self.expect('SELECT'); q={'kind':'select'}
        q['distinct']=bool(self.take('DISTINCT'))
        if not q['distinct']: self.take('ALL')
        q['items']=self.select_items()
        if self.take('FROM'): q['from']=self.from_clause()
        if self.take('WHERE'): q['where']=self.expr()
        if self.take('GROUP'):
            self.expect('BY'); q['group']=self.exprlist()
        if self.take('HAVING'): q['having']=self.expr()
        if self.take('WINDOW'):
            wins={}
            while True:
                name=self.ident(); self.expect('AS'); self.expect('('); wins[name.lower()]=self.window_spec(); self.expect(')')
                if not self.take(','): break
            q['windows']=wins
        return q

    def statement(self):
        while self.take(';'): pass
        if self.t.kind=='eof': return None
        start=self.t.pos
        q=None
        ctes=[]; recursive=False
        if self.at('WITH'):
            # A WITH prefix may be followed by a query or a data modification.
            saved=self.i; ctes,recursive=self.with_clause()
            if self.at('SELECT','VALUES'):
                self.i=saved; q=self.query(); ctes=[]
        if q is None:
            if self.at('SELECT','VALUES'): q=self.query()
            elif self.at('EXPLAIN'):
                self.pop(); plan=bool(self.take('QUERY'))
                if plan: self.expect('PLAN')
                q={'kind':'explain','plan':plan,'statement':self.statement()}
            elif self.at('CREATE'): q=self.create()
            elif self.at('INSERT','REPLACE'): q=self.insert()
            elif self.at('UPDATE'): q=self.update()
            elif self.at('DELETE'): q=self.delete()
