                if self.take('IF'): self.expect('EXISTS'); exists=True
                q={'kind':'drop','type':typ.lower(),'name':self.fullname(),'ifexists':exists}
            elif self.at('ALTER'): q=self.alter()
            elif self.at('PRAGMA'): q=self.pragma()
            elif self.at('ATTACH'):
                self.pop(); self.take('DATABASE'); path=self.expr(); self.expect('AS'); name=self.expr()
                q={'kind':'attach','path':path,'name':name}
