def json_path(path, abbreviated=False):
    if abbreviated and isinstance(path,int): return [('index',path)]
    if path is None: return None
    path=to_text(path)
    if abbreviated and not path.startswith('$'):
        if re.fullmatch(r'-?\d+',path): return [('index',int(path))]
        return [('key',path)]
    if not path.startswith('$'): raise SQLError('bad JSON path: '+sql_quote(path),runtime=True)
    out=[]; i=1
    while i<len(path):
