                if i==j: raise SQLError('bad JSON path: '+sql_quote(path),runtime=True)
                out.append(('key',path[j:i]))
        elif path[i]=='[':
            j=path.find(']',i)
            if j<0: raise SQLError('bad JSON path: '+sql_quote(path),runtime=True)
            v=path[i+1:j]
