            elif re.fullmatch(r'#-\d+',v): out.append(('index',-int(v[2:])))
            elif v.isdigit(): out.append(('index',int(v)))
            else: raise SQLError('bad JSON path: '+sql_quote(path),runtime=True)
            i=j+1
        else: raise SQLError('bad JSON path: '+sql_quote(path),runtime=True)
    return out

def json_get(obj,path):
    if path is None: return MISSING
    for kind,key in path:
        if kind=='key':
            if not isinstance(obj,dict) or key not in obj: return MISSING
            obj=obj[key]
        else:
            if not isinstance(obj,list): return MISSING
            if kind=='append': return MISSING
            if key<0: key+=len(obj)
            if not 0<=key<len(obj): return MISSING
            obj=obj[key]
    return obj

def json_sql(v):
    if v is MISSING or v is None: return None
    if isinstance(v,bool): return int(v)
    if isinstance(v,(list,dict)): return JsonText(json_encode(v))
