def json_type(v):
    if v is MISSING: return None
    if v is None: return 'null'
    if isinstance(v,bool): return 'true' if v else 'false'
    if isinstance(v,int): return 'integer'
    if isinstance(v,float): return 'real'
    if isinstance(v,str): return 'text'
    if isinstance(v,list): return 'array'
    return 'object'

def json_set_path(obj,path,value,op):
    if path is None: return obj
    if not path:
        return None if op=='remove' else (value if op in ('set','replace') else obj)
    cur=obj
    for ix,(kind,key) in enumerate(path):
        last=ix==len(path)-1
        if kind=='key':
            if not isinstance(cur,dict): return obj
            exists=key in cur
            if last:
                if op=='remove': cur.pop(key,None)
                elif op=='set' or op=='replace' and exists or op in ('insert','array_insert') and not exists: cur[key]=value
            else:
                if not exists:
                    if op not in ('set','insert'): return obj
                    cur[key]= {} if path[ix+1][0]=='key' else []
                cur=cur[key]
        else:
            if not isinstance(cur,list): return obj
            if kind=='append': key=len(cur)
            elif key<0: key+=len(cur)
            if key<0 or key>len(cur): return obj
            exists=key<len(cur)
            if last:
                if op=='remove':
                    if exists: cur.pop(key)
                elif op=='array_insert': cur.insert(key,value)
                elif op=='replace':
                    if exists: cur[key]=value
                elif op=='set':
                    if exists: cur[key]=value
                    else: cur.append(value)
                elif op=='insert' and not exists: cur.append(value)
            else:
                if not exists:
                    if op not in ('set','insert'): return obj
                    cur.append({} if path[ix+1][0]=='key' else [])
                cur=cur[key]
    return obj

def merge_patch(target,patch):
    if not isinstance(patch,dict): return copy.deepcopy(patch)
    if not isinstance(target,dict): target={}
    for k,v in patch.items():
        if v is None: target.pop(k,None)
        else: target[k]=merge_patch(target.get(k),v)
    return target

# Compact binary JSON uses a type nibble and a length-prefixed payload.
def jsonb_encode(v):
    if v is None: t,p=0,b''
    elif v is True: t,p=1,b''
    elif v is False: t,p=2,b''
    elif isinstance(v,int): t,p=3,str(v).encode()
    elif isinstance(v,float): t,p=5,to_text(v).encode()
    elif isinstance(v,str):
        esc=json.dumps(v,ensure_ascii=False)[1:-1]; p=esc.encode('utf-8'); t=8 if '\\' in esc else 7
    elif isinstance(v,list): t,p=11,b''.join(jsonb_encode(x) for x in v)
    elif isinstance(v,dict): t,p=12,b''.join(jsonb_encode(str(k))+jsonb_encode(x) for k,x in v.items())
    else: raise SQLError('JSON cannot hold BLOB values',runtime=True)
    n=len(p)
    if n<12: return bytes([(n<<4)|t])+p
    if n<256: return bytes([0xc0|t,n])+p
    if n<65536: return bytes([0xd0|t])+struct.pack('>H',n)+p
    if n<2**32: return bytes([0xe0|t])+struct.pack('>I',n)+p
    return bytes([0xf0|t])+struct.pack('>Q',n)+p

def jsonb_decode(b,start=0):
    h=b[start]; n=h>>4; t=h&15; p=start+1
    if n>=12:
        size=1<<(n-12); n=int.from_bytes(b[p:p+size],'big'); p+=size
    end=p+n
    if end>len(b): raise ValueError()
    payload=b[p:end]
    if t==0: v=None
    elif t==1: v=True
    elif t==2: v=False
    elif t in (3,4): v=int(payload.decode(),0 if t==4 else 10)
    elif t in (5,6): v=float(payload.decode())
    elif t in (7,8,9,10):
        v=payload.decode('utf-8')
        if t==8: v=json.loads('"'+v+'"')
    elif t in (11,12):
        arr=[]
        while p<end:
            x,p=jsonb_decode(b,p); arr.append(x)
        v=arr if t==11 else dict(zip(arr[::2],arr[1::2]))
    else: raise ValueError()
    return v,end


def json_function(name,args):
    binary=name.startswith('jsonb')
    name=name.replace('jsonb','json',1)
    if name=='json_valid':
        if not args or args[0] is None: return None
        if isinstance(args[0],bytes) and len(args)>1 and to_num(args[1],True)&12:
            try: jsonb_decode(args[0]); return 1
            except Exception: return 0
        try:
            if len(args)>1 and to_num(args[1],True)&2: json_parse(args[0])
            else: json.loads(to_text(args[0]))
            return 1
        except Exception: return 0
    if name=='json_error_position':
        if args[0] is None: return None
        try: json_parse(args[0]); return 0
        except SQLError:
            try: json.loads(to_text(args[0]))
            except json.JSONDecodeError as e: return e.pos+1
            return 1
    if name=='json_quote':
        if isinstance(args[0],JsonText): return args[0]
        v=json_value(args[0])
    elif name=='json_array': v=[json_value(x) for x in args]
