        v=json_parse(args[0])
        if name=='json_array_length':
            if len(args)>1: v=json_get(v,json_path(args[1]))
            return None if v is MISSING else len(v) if isinstance(v,list) else 0
        if name=='json_type':
            if len(args)>1: v=json_get(v,json_path(args[1]))
            return json_type(v)
        if name=='json_extract':
            if len(args)<2: return None
            vals=[json_get(v,json_path(p)) for p in args[1:]]
            if len(vals)==1:
                if binary and isinstance(vals[0],(list,dict)): return jsonb_encode(vals[0])
                return json_sql(vals[0])
            v=[None if x is MISSING else x for x in vals]
        elif name=='json_patch':
            if args[1] is None: return None
            v=merge_patch(v,json_parse(args[1]))
        elif name in ('json_set','json_insert','json_replace','json_array_insert'):
            if len(args)%2==0: raise SQLError(name+'() needs an odd number of arguments',runtime=True)
            for p,x in zip(args[1::2],args[2::2]): v=json_set_path(v,json_path(p),json_value(x),name[5:])
