            indent='    ' if len(args)<2 or args[1] is None else to_text(args[1])
            return JsonText(json_encode(v,indent))
    if binary: return jsonb_encode(v)
    try: return JsonText(json_encode(v))
    except ValueError:
        return JsonText(json.dumps(v,ensure_ascii=False,separators=(',',':')).replace('Infinity','9e999').replace('NaN','null'))


def date_function(name,args):
    fmt=None
    if name=='strftime':
        if not args or args[0] is None: return None
        fmt=to_text(args[0]); args=args[1:]
    if name=='timediff':
        if len(args)<2: return None
        a=date_parse([args[0]]); b=date_parse([args[1]])
        if a is None or b is None: return None
        a,b=a[0],b[0]; neg=a<b
        if neg: a,b=b,a
        months=(a.year-b.year)*12+a.month-b.month
        def addmonth(x,m):
            y=x.year+(x.month-1+m)//12; mm=(x.month-1+m)%12+1
            return x.replace(year=y,month=mm,day=min(x.day,calendar.monthrange(y,mm)[1]))
        while months>0 and addmonth(b,months)>a: months-=1
        delta=a-addmonth(b,months); days=delta.days; seconds=delta.seconds; ms=round(delta.microseconds/1000)
        return '%s%04d-%02d-%02d %02d:%02d:%02d.%03d'%('-' if neg else '+',months//12,months%12,days,seconds//3600,seconds//60%60,seconds%60,ms)
    parsed=date_parse(args)
    if parsed is None: return None
    v,subsec=parsed
    epoch=(v-dt.datetime(1970,1,1)).total_seconds()
    jd=epoch/86400+2440587.5
    if name=='unixepoch': return round(epoch,3) if subsec else math.floor(epoch)
    if name=='julianday': return jd
    date='%04d-%02d-%02d'%(v.year,v.month,v.day)
    timestr=v.strftime('%H:%M:%S')+('.%03d'%round(v.microsecond/1000) if subsec else '')
    if name=='date': return date
    if name=='time': return timestr
    if name=='datetime': return date+' '+timestr
    if name=='strftime':
        iso=v.isocalendar()
        mapping={'d':f'{v.day:02}','e':f'{v.day:2}','f':f'{v.second:02}.{v.microsecond//1000:03}','F':date,'G':f'{iso[0]:04}','g':f'{iso[0]%100:02}','H':f'{v.hour:02}','I':f'{(v.hour-1)%12+1:02}','j':v.strftime('%j'),'J':format(jd,'.16g'),'k':f'{v.hour:2}','l':f'{(v.hour-1)%12+1:2}','m':f'{v.month:02}','M':f'{v.minute:02}','p':'AM' if v.hour<12 else 'PM','P':'am' if v.hour<12 else 'pm','R':v.strftime('%H:%M'),'s':str(math.floor(epoch)) if not subsec else f'{epoch:.3f}','S':f'{v.second:02}','T':v.strftime('%H:%M:%S'),'U':v.strftime('%U'),'u':str(iso[2]),'V':f'{iso[1]:02}','w':str((v.weekday()+1)%7),'W':v.strftime('%W'),'Y':f'{v.year:04}','%':'%'}
        out=''; i=0
