            if fmt[i]=='%':
                i+=1
                if i==len(fmt) or fmt[i] not in mapping: return None
                out+=mapping[fmt[i]]
            else: out+=fmt[i]
            i+=1
        return out
    return None

def date_parse(args):
    if not args: args=['now']
    if any(x is None for x in args): return None
    val=args[0]; mods=[to_text(x).lower() for x in args[1:]]; subsec=False
    if to_text(val).lower() in ('subsec','subsecond'):
        mods=[to_text(val).lower()]+mods; val='now'
    try:
        if isinstance(val,(int,float)) or re.fullmatch(r'[+-]?\d+(\.\d+)?',to_text(val)):
            num=float(val)
            unix='unixepoch' in mods or ('auto' in mods and not (0<=num<=5373484.499999))
            v=dt.datetime(1970,1,1)+dt.timedelta(seconds=num if unix else (num-2440587.5)*86400)
        else:
            s=to_text(val).strip()
            if s.lower()=='now': v=dt.datetime.now(dt.timezone.utc).replace(tzinfo=None)
            else:
                if re.match(r'^\d\d:\d\d',s): s='2000-01-01 '+s
                s=s.replace('T',' ')
                if s.endswith('Z'): s=s[:-1]+'+00:00'
                if re.search(r' 24:',s):
                    s=s.replace(' 24:',' 00:'); v=dt.datetime.fromisoformat(s)+dt.timedelta(days=1)
                else: v=dt.datetime.fromisoformat(s)
                if v.tzinfo: v=v.astimezone(dt.timezone.utc).replace(tzinfo=None)
        v=v.replace(microsecond=(v.microsecond+500)//1000*1000 if v.microsecond<999500 else 999000)
        prior=None
        for mod in mods:
            if mod in ('unixepoch','auto','julianday'): continue
            if mod in ('subsec','subsecond'): subsec=True; continue
            if mod=='localtime': v=dt.datetime.fromtimestamp(calendar.timegm(v.timetuple())).replace(microsecond=v.microsecond); continue
            if mod=='utc': v=dt.datetime.utcfromtimestamp(time.mktime(v.timetuple())).replace(microsecond=v.microsecond); continue
            if mod=='floor':
                if prior: v=prior
                continue
            if mod=='ceiling': continue
            if mod.startswith('start of '):
                unit=mod[9:]; v=v.replace(hour=0,minute=0,second=0,microsecond=0)
                if unit=='month': v=v.replace(day=1)
                elif unit=='year': v=v.replace(month=1,day=1)
                elif unit!='day': return None
                continue
            m=re.fullmatch(r'weekday\s+([0-6])',mod)
            if m:
                v+=dt.timedelta(days=(int(m[1])-(v.weekday()+1)%7)%7); continue
            m=re.fullmatch(r'([+-]?\d+(?:\.\d+)?)\s+(days?|hours?|minutes?|seconds?|months?|years?)',mod)
            if m:
                n=float(m[1]); unit=m[2].rstrip('s')
                if unit in ('month','year'):
                    months=int(n)*(12 if unit=='year' else 1); frac=n-int(n)
                    y=v.year+(v.month-1+months)//12; mm=(v.month-1+months)%12+1
                    ndays=calendar.monthrange(y,mm)[1]; prior=v.replace(year=y,month=mm,day=min(v.day,ndays))
                    v=v.replace(year=y,month=mm,day=1)+dt.timedelta(days=v.day-1+frac*(365 if unit=='year' else 30))
                else: v+=dt.timedelta(seconds=n*{'day':86400,'hour':3600,'minute':60,'second':1}[unit])
                continue
            m=re.fullmatch(r'([+-])(\d\d):(\d\d)(?::(\d\d(?:\.\d+)?))?',mod)
            if m:
                sec=int(m[2])*3600+int(m[3])*60+float(m[4] or 0); v+=dt.timedelta(seconds=sec*(-1 if m[1]=='-' else 1)); continue
            return None
        return v,subsec
    except (ValueError,OverflowError,TypeError,OSError): return None


def decimal_func(name,args):
